begin;
select set_config('test.a',gen_random_uuid()::text,true),set_config('test.b',gen_random_uuid()::text,true),set_config('test.c',gen_random_uuid()::text,true),set_config('test.mid',gen_random_uuid()::text,true);
insert into auth.users(id,aud,role,email) select current_setting('test.'||x)::uuid,'authenticated','authenticated',x||'-messages@example.invalid' from unnest(array['a','b','c'])x;
insert into public.profiles(id,display_name,username,bio) select current_setting('test.'||x)::uuid,'Prueba '||x,'msg_'||substr(replace(current_setting('test.'||x),'-',''),1,16),'Prueba temporal' from unnest(array['a','b','c'])x;
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('test.a'),true);
insert into public.conversations(user_low,user_high) values(least(current_setting('test.a')::uuid,current_setting('test.b')::uuid),greatest(current_setting('test.a')::uuid,current_setting('test.b')::uuid));
select set_config('test.chat',(select id::text from public.conversations),true);
insert into public.messages(id,conversation_id,sender_id,body) values(current_setting('test.mid')::uuid,current_setting('test.chat')::uuid,current_setting('test.a')::uuid,'¿Vamos al café?');
insert into public.messages(id,conversation_id,sender_id,body) values(current_setting('test.mid')::uuid,current_setting('test.chat')::uuid,current_setting('test.a')::uuid,'¿Vamos al café?') on conflict(id) do nothing;
select set_config('test.saved',((select count(*) from public.messages)=1)::text,true);
select set_config('test.inbox',((select last_body from public.chat_inbox)='¿Vamos al café?')::text,true);
do $$ begin begin insert into public.messages(id,conversation_id,sender_id,body) values(gen_random_uuid(),current_setting('test.chat')::uuid,current_setting('test.b')::uuid,'Falso'); perform set_config('test.spoof','false',true); exception when insufficient_privilege then perform set_config('test.spoof','true',true); end;end $$;
do $$ begin begin insert into public.messages(id,conversation_id,sender_id,body) values(gen_random_uuid(),current_setting('test.chat')::uuid,current_setting('test.a')::uuid,'   '); perform set_config('test.blank','false',true); exception when check_violation then perform set_config('test.blank','true',true); end;end $$;
do $$ begin begin insert into public.messages(id,conversation_id,sender_id,body) values(gen_random_uuid(),current_setting('test.chat')::uuid,current_setting('test.a')::uuid,repeat('x',1001)); perform set_config('test.long','false',true); exception when check_violation then perform set_config('test.long','true',true); end;end $$;
do $$ begin begin insert into public.messages(id,conversation_id,sender_id,body,created_at) values(gen_random_uuid(),current_setting('test.chat')::uuid,current_setting('test.a')::uuid,'Fecha falsa',now()+interval '1 year'); perform set_config('test.time','false',true); exception when insufficient_privilege then perform set_config('test.time','true',true); end;end $$;
do $$ begin begin insert into public.conversations(user_low,user_high) values(current_setting('test.a')::uuid,current_setting('test.a')::uuid); perform set_config('test.self','false',true); exception when check_violation then perform set_config('test.self','true',true); end;end $$;
do $$ begin begin update public.messages set body='Editado'; perform set_config('test.edit','false',true); exception when insufficient_privilege then perform set_config('test.edit','true',true); end;end $$;
select set_config('request.jwt.claim.sub',current_setting('test.b'),true);
select set_config('test.recipient',((select count(*) from public.messages)=1)::text,true);
insert into public.messages(id,conversation_id,sender_id,body) values(gen_random_uuid(),current_setting('test.chat')::uuid,current_setting('test.b')::uuid,'¡Sí!');
select set_config('request.jwt.claim.sub',current_setting('test.a'),true);
select set_config('test.reply',((select count(*) from public.messages)=2 and (select last_body from public.chat_inbox) in ('¡Sí!','¿Vamos al café?'))::text,true);
select set_config('request.jwt.claim.sub',current_setting('test.c'),true);
select set_config('test.private',((select count(*) from public.messages)=0 and (select count(*) from public.chat_inbox)=0 and (select count(*) from public.conversations)=0)::text,true);
do $$ begin begin insert into public.messages(id,conversation_id,sender_id,body) values(gen_random_uuid(),current_setting('test.chat')::uuid,current_setting('test.c')::uuid,'Intruso'); perform set_config('test.outsider','false',true); exception when insufficient_privilege then perform set_config('test.outsider','true',true); end;end $$;
set local role anon;
do $$ begin begin select * from public.messages; perform set_config('test.anonymous','false',true); exception when insufficient_privilege then perform set_config('test.anonymous','true',true); end;end $$;
select label as check_name,current_setting('test.'||label)='true' as passed from (values ('saved'),('inbox'),('spoof'),('blank'),('long'),('time'),('self'),('edit'),('recipient'),('reply'),('private'),('outsider'),('anonymous'))checks(label);
rollback;